import{_ as e,o as a,c as d,ag as r}from"./chunks/framework.BcZEdlUI.js";const A=JSON.parse('{"title":"架构决策记录 (ADR)","description":"SceneFab 关键架构决策的背景、权衡与结论汇总。","frontmatter":{"title":"架构决策记录 (ADR)","description":"SceneFab 关键架构决策的背景、权衡与结论汇总。"},"headers":[],"relativePath":"adr/index.md","filePath":"adr/index.md","lastUpdated":1781612722000}'),c={name:"adr/index.md"};function n(o,t,s,i,l,h){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="架构决策记录-adr" tabindex="-1">架构决策记录 (ADR) <a class="header-anchor" href="#架构决策记录-adr" aria-label="Permalink to &quot;架构决策记录 (ADR)&quot;">​</a></h1><p>ADR（Architecture Decision Record）记录 SceneFab 在演进过程中做出的关键架构决策：<strong>为什么这样选、权衡了什么、结论是否仍然成立</strong>。每条 ADR 都是一次性写定的历史记录，便于新成员理解系统现状的由来。</p><table tabindex="0"><thead><tr><th>编号</th><th>决策</th><th>状态</th></tr></thead><tbody><tr><td><a href="/scene-fab/adr/001-pyside6-vs-electron.html">ADR-001</a></td><td>PySide6 vs Electron 作为桌面端 GUI 框架</td><td>✅ Accepted</td></tr><tr><td><a href="/scene-fab/adr/002-local-processing-vs-cloud-rendering.html">ADR-002</a></td><td>全量本地处理 vs 云端渲染</td><td>✅ Accepted</td></tr><tr><td><a href="/scene-fab/adr/003-event-driven-ioc-architecture.html">ADR-003</a></td><td>事件驱动 + IoC 容器架构</td><td>✅ Accepted</td></tr><tr><td><a href="/scene-fab/adr/004-dag-parallel-pipeline.html">ADR-004</a></td><td>DAG 并行流水线 vs 串行流水线</td><td>✅ Accepted (v2.0)</td></tr><tr><td><a href="/scene-fab/adr/005-f5-tts-vs-cloud-tts.html">ADR-005</a></td><td>F5-TTS 本地零样本 vs 云端 TTS</td><td>✅ Accepted</td></tr><tr><td><a href="/scene-fab/adr/006-v21-architecture-upgrade.html">ADR-006</a></td><td>v2.1 架构升级：单源真相 + 类型化事件 + DI 现代化</td><td>✅ Accepted</td></tr><tr><td><a href="/scene-fab/adr/007-narration-state-machine.html">ADR-007</a></td><td>解说生成状态机：上下文工程 + 状态机流水线</td><td>✅ Accepted</td></tr></tbody></table><h2 id="阅读建议" tabindex="-1">阅读建议 <a class="header-anchor" href="#阅读建议" aria-label="Permalink to &quot;阅读建议&quot;">​</a></h2><ul><li>想了解<strong>整体形态</strong>：先读 ADR-001 / ADR-002（桌面端 + 本地优先的两条产品基线）。</li><li>想了解<strong>运行时架构</strong>：ADR-003 / ADR-006（事件总线 + DI 容器）与 ADR-004（并行流水线）。</li><li>想了解<strong>解说生成核心</strong>：ADR-007（状态机 + 四类上下文），并对照<a href="/scene-fab/architecture.html">架构概览</a>。</li></ul><blockquote><p>这些决策的当前落地形态见<a href="/scene-fab/architecture.html">架构概览</a>；面向开发者的弃用与迁移计划见仓库内 <code>docs/deprecations.md</code>（不在本站导航）。</p></blockquote>',6)])])}const f=e(c,[["render",n]]);export{A as __pageData,f as default};
